UPDATE ui.dashboardquery SET
vcdashboardquery =  E'{"Initial": 
{"All": "select result->''score''->>''decisiondetails'' as \\"decisiondetails\\", ilivemessageid as \\"ILiveMessageID\\", vcmsgid as \\"UniqueID\\", vcclassname as \\"Class\\", dttrxntime at time zone ''Asia/Kolkata'' at time zone :timeZone as \\"Time\\", dobservationamount as \\"Amount\\", score as \\"Score\\",  case when result->>''status''=''Failed'' then ''false'' else ''true'' end as \\"FRMPass\\", vcpayeraccountexternalid as \\"Payer Account\\", vcpayeraddr as \\"PayerVPA\\", vcpayeeaccountexternalid as \\"Payee Account\\", vcpayeeaddr as \\"PayeeVPA\\", null as \\"FailedRule\\", cast(observations->''observations''->''payerVPA''->>''vpaName'' as text) as \\"PayerName\\",  cast(observations->''observations''->''payeeVPA''->>''vpaName'' as text) as \\"PayeeName\\" from analytics.trans where vcclassname in (with d1 as (select mappingid from ui.webusermapping where webuserid = :loggedinuser and mappingtype = ''TransactionClass'') (select vcclassname FROM ui.transactionclasses where (iclassid in (select mappingid from d1) or -1 in (select mappingid from d1)) and itenantid=:tenantid)) and score >= :score and dttrxntime > cast(current_date as timestamp) and itenantid = :tenantid order by dttrxntime desc limit 50;",
"Other": "select result->''score''->>''decisiondetails'' as \\"decisiondetails\\", ilivemessageid as \\"ILiveMessageID\\", vcmsgid as \\"UniqueID\\", vcclassname as \\"Class\\", dttrxntime at time zone ''Asia/Kolkata'' at time zone :timeZone as \\"Time\\", dobservationamount as \\"Amount\\", score as \\"Score\\",  case when result->>''status''=''Failed'' then ''false'' else ''true'' end as \\"FRMPass\\", vcpayeraccountexternalid as \\"Payer Account\\", vcpayeraddr as \\"PayerVPA\\", vcpayeeaccountexternalid as \\"Payee Account\\", vcpayeeaddr as \\"PayeeVPA\\", null as \\"FailedRule\\", cast(observations->''observations''->''payerVPA''->>''vpaName'' as text) as \\"PayerName\\",  cast(observations->''observations''->''payeeVPA''->>''vpaName'' as text) as \\"PayeeName\\" from analytics.trans where score >= :score and dttrxntime > cast(current_date as timestamp) and vcclassname  = :className and itenantid = :tenantid order by dttrxntime desc limit 50;"},
"Refresh":
    {
    "All": " select result->''score''->>''decisiondetails'' as \\"decisiondetails\\", ilivemessageid as \\"ILiveMessageID\\", vcmsgid as \\"UniqueID\\", vcclassname as \\"Class\\", dttrxntime at time zone ''Asia/Kolkata'' at time zone :timeZone as \\"Time\\", dobservationamount as \\"Amount\\", score as \\"Score\\",  case when result->>''status''=''Failed'' then ''false'' else ''true'' end as \\"FRMPass\\", vcpayeraccountexternalid as \\"Payer Account\\", vcpayeraddr as \\"PayerVPA\\", vcpayeeaccountexternalid as \\"Payee Account\\", vcpayeeaddr as \\"PayeeVPA\\", null as \\"FailedRule\\", cast(observations->''observations''->''payerVPA''->>''vpaName'' as text) as \\"PayerName\\",  cast(observations->''observations''->''payeeVPA''->>''vpaName'' as text) as \\"PayeeName\\" from analytics.trans where vcclassname in (with d1 as (select mappingid from ui.webusermapping where webuserid = :loggedinuser and mappingtype = ''TransactionClass'') (select vcclassname FROM ui.transactionclasses where (iclassid in (select mappingid from d1) or -1 in (select mappingid from d1)) and itenantid=:tenantid)) and score >= :score and ilivemessageid > :iLiveMessageID and itenantid = :tenantid order by dttrxntime desc limit 1000;",
    "Other": "select result->''score''->>''decisiondetails'' as \\"decisiondetails\\", ilivemessageid as \\"ILiveMessageID\\", vcmsgid as \\"UniqueID\\", vcclassname as \\"Class\\", dttrxntime at time zone ''Asia/Kolkata'' at time zone :timeZone as \\"Time\\", dobservationamount as \\"Amount\\", score as \\"Score\\",  case when result->>''status''=''Failed'' then ''false'' else ''true'' end as \\"FRMPass\\", vcpayeraccountexternalid as \\"Payer Account\\", vcpayeraddr as \\"PayerVPA\\", vcpayeeaccountexternalid as \\"Payee Account\\", vcpayeeaddr as \\"PayeeVPA\\", null as \\"FailedRule\\", cast(observations->''observations''->''payerVPA''->>''vpaName'' as text) as \\"PayerName\\",  cast(observations->''observations''->''payeeVPA''->>''vpaName'' as text) as \\"PayeeName\\" from analytics.trans  where score >= :score and vcclassname  = :className and ilivemessageid > :iLiveMessageID and itenantid = :tenantid order by dttrxntime desc limit 1000;"}
}'::text WHERE
idashboardqueryid = 55;